    return;
  }
  if (!verb || verb === "help" || isHelpFlag(verb)) {
    printHelp(write);
    return;
  }
  const lines = usageLinesFor(verb);
  if (lines) {
    write(`\nroleos ${verb}\n\nUsage:\n${lines}\n`);
  } else {
    printHelp(write);
  }
}

